.matrix-wrap { position: relative; width: 100%; height: 300vh; }
#matrix-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.matrix-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.matrix-msg {
  position: absolute; color: #00ffcc; font-size: 30px; font-weight: 900; text-align: center;
  opacity: 0; transition: opacity 0.3s; text-shadow: 0 0 20px #00ffcc; font-family: monospace;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#02050a;position:relative;';

c.innerHTML = `
  <div class="matrix-wrap">
    <canvas id="matrix-canvas"></canvas>
    <div class="matrix-text-layer">
      <div id="mMsg1" class="matrix-msg" style="top:15%;">SYSTEM BOOT... ↓</div>
      <div id="mMsg2" class="matrix-msg" style="font-size:45px;">KAVACH</div>
      <div id="mMsg3" class="matrix-msg" style="font-size:50px; color:#ff007f;">SECURED</div>
    </div>
  </div>
`;

const mCvs = document.getElementById('matrix-canvas');
const mCtx = mCvs.getContext('2d');
let mW, mH;
let mParticles = [], mShapes = [];
const mCount = 800;

function getMatrixPts(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = mW; tc.height = mH;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px monospace`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, mW/2, mH/2);
  const data = tctx.getImageData(0,0,mW,mH).data;
  let pts = [];
  for(let y=0; y<mH; y+=7){
    for(let x=0; x<mW; x+=7){
      if(data[(y*mW+x)*4+3] > 128) pts.push({x:x, y:y});
    }
  }
  return pts.length ? pts : [{x: mW/2, y: mH/2}];
}

function initMatrix() {
  mW = mCvs.width = window.innerWidth;
  mH = mCvs.height = window.innerHeight;

  let s1 = []; 
  for(let i=0; i<mCount; i++) s1.push({x: Math.random()*mW, y: Math.random()*mH});

  let s2 = getMatrixPts('KAVACH', Math.min(mW/4, 60));
  let s3 = getMatrixPts('SECURE', Math.min(mW/4, 60));

  mShapes = [s1, s2, s3, s3];
  mParticles = [];
  for(let i=0; i<mCount; i++){
    mParticles.push({ x: Math.random()*mW, y: Math.random()*mH, c: '#00ffcc', speed: Math.random()*5+2 }); 
  }
}
initMatrix(); window.addEventListener('resize', initMatrix);

let mProg = 0;
c.addEventListener('scroll', () => {
  mProg = c.scrollTop / (c.scrollHeight - c.clientHeight);
  document.getElementById('mMsg1').style.opacity = (mProg < 0.1) ? 1 : 0;
  document.getElementById('mMsg2').style.opacity = (mProg > 0.35 && mProg < 0.6) ? 1 : 0;
  document.getElementById('mMsg3').style.opacity = (mProg > 0.8) ? 1 : 0;
});

// ERROR FIXED HERE: lerp ફંક્શન ઉમેર્યું છે
function lerp(a, b, t) { return a + (b - a) * t; }

function drawMatrix() {
  mCtx.fillStyle = 'rgba(2, 5, 10, 0.3)'; 
  mCtx.fillRect(0,0,mW,mH);

  let stage = mProg * 3;
  let cStage = Math.floor(stage);
  let nStage = Math.min(cStage + 1, 3);
  let tProg = stage - cStage;

  let pts1 = mShapes[cStage], pts2 = mShapes[nStage];

  for(let i=0; i<mCount; i++){
    let p = mParticles[i];
    let t1 = pts1[i % pts1.length], t2 = pts2[i % pts2.length];

    let tx = lerp(t1.x, t2.x, tProg), ty = lerp(t1.y, t2.y, tProg);

    if(cStage === 0) { 
        ty = (p.y + p.speed) % mH;
        tx = p.x;
    }

    p.x += (tx - p.x) * 0.1; p.y += (ty - p.y) * 0.1;

    mCtx.fillStyle = (Math.random() > 0.9) ? '#fff' : p.c; 
    mCtx.font = '12px monospace';
    mCtx.fillText(Math.random() > 0.5 ? '0' : '1', p.x, p.y);
  }
  requestAnimationFrame(drawMatrix);
}
drawMatrix();
